CREATE OR REPLACE FUNCTION public.mark_news_seen(until timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  kept timestamptz;
begin
  if me is null or not coalesce(public.is_allowed_user(), false) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if until is null then
    raise exception 'mark_news_seen: invalid' using errcode = '22023';
  end if;
  insert into public.news_reads as r (user_id, seen_until) values (me, least(until, now()))
  on conflict (user_id) do update set
    seen_until = greatest(r.seen_until, excluded.seen_until),
    updated_at = now()
  returning r.seen_until into kept;
  return kept;
end;
$function$;

grant execute on function public.mark_news_seen(until timestamp with time zone) to authenticated;
grant execute on function public.mark_news_seen(until timestamp with time zone) to service_role;
